  Future<void> _checkUserValidity() async {
    final user = FirebaseAuth.instance.currentUser;

    try {
      await user?.reload();
      final refreshedUser = FirebaseAuth.instance.currentUser;

      if (refreshedUser == null) {
        // Usuario eliminado de Authentication
        await FirebaseAuth.instance.signOut();
        _navigateToLogin();
        return;
      }

      await Future.delayed(const Duration(milliseconds: 500));

      final firestore = FirebaseFirestore.instance;

      // 1️⃣ Verificar si existe el documento en la colección 'users'
      final userDoc =
          await firestore.collection('users').doc(refreshedUser.email).get();

      if (!userDoc.exists) {
        await FirebaseAuth.instance.signOut();
        _navigateToLogin();
        return;
      }
    } catch (e) {
      print('❌ Error validando usuario o posts: $e');
      await FirebaseAuth.instance.signOut();
      _navigateToLogin();
    }
  }

  void _navigateToLogin() {
    if (mounted) {
      Navigator.of(context).pushAndRemoveUntil(
        MaterialPageRoute(builder: (_) => const OnboardingPage()),
        (route) => false,
      );
    }
  }

  Future<void> getUserRole() async {
    final email = FirebaseAuth.instance.currentUser?.email;
    if (email == null) return;

    final doc =
        await FirebaseFirestore.instance.collection('users').doc(email).get();
    if (doc.exists) {
      setState(() {
        userRole = doc.data()?['rol'] ?? '';
      });
    }
  }

  Future<void> getUserName() async {
    final email = FirebaseAuth.instance.currentUser?.email;
    if (email == null) return;

    final doc =
        await FirebaseFirestore.instance.collection('users').doc(email).get();
    if (doc.exists) {
      setState(() {
        userRole = doc.data()?['Name'] ?? '';
      });
    }
  }

